<?php require_once __DIR__.'/_header.php';$rows=db()->query("SELECT l.*,u.email FROM system_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 200")->fetchAll();?><div class="page-head"><div><h1>System Logs</h1><p>Administrative actions and application events.</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['email']??'system')?></td><td><span class="badge published"><?=e($r['action'])?></span></td><td><?=e($r['details']??'')?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_footer.php';